### 1. Depth-First Search (DFS)

Depth-First Search is a recursive algorithm that explores as far as possible along each branch before backtracking.

```python
def dfs(graph, start, goal):
    visited = set()
    stack = [(start, [start])]  # (current node, path taken to reach current node)

    while stack:
        (node, path) = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    return None
```

### 2. Breadth-First Search (BFS)

Breadth-First Search explores the graph level by level, starting from the root. It's useful for finding the shortest path in an unweighted graph.

```python
def bfs(graph, start, goal):
    visited = set()
    queue = [(start, [start])]  # (current node, path taken to reach current node)

    while queue:
        (node, path) = queue.pop(0)
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))
    return None
```

### 3. A\*-Search

A\*-Search is an informed search algorithm that uses a heuristic to guide the search towards the goal. It's often used for pathfinding and graph traversal with weighted edges.

```python
def a_star_search(graph, start, goal, heuristic):
    open_list = []
    closed_set = set()
    g_scores = {start: 0}
    f_scores = {start: heuristic[start]}
    prev = {}

    open_list.append((start, 0, f_scores[start]))

    while open_list:
        current = min(open_list, key=lambda x: f_scores[x[0]])
        open_list.remove(current)
        closed_set.add(current[0])

        if current[0] == goal:
            path = []
            while current[0] in prev:
                path.insert(0, current[0])
                current = prev[current[0]]
            return path

        for neighbor in graph[current[0]]:
            tentative_g_score = g_scores[current[0]] + 1

            if neighbor not in g_scores or tentative_g_score < g_scores[neighbor]:
                g_scores[neighbor] = tentative_g_score
                f_scores[neighbor] = g_scores[neighbor] + heuristic[neighbor]
                prev[neighbor] = current[0]

                if neighbor not in closed_set:
                    open_list.append((neighbor, g_scores[neighbor], f_scores[neighbor]))

    return None
```

