    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v, weight):
        if u not in self.graph:
            self.graph[u] = {}
        self.graph[u][v] = weight

    def get_neighbors(self, node):
        return self.graph.get(node, {})

    def vertices(self):
        return list(self.graph.keys())

def shortest_path_dijkstra(graph, start, end):
    # Shortest path using Dijkstra's algorithm
    import heapq

    # Priority queue to fetch nodes with minimum distance
    priority_queue = [(0, start)]
    distances = {node: float('infinity') for node in graph.vertices()}
    distances[start] = 0

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph.get_neighbors(current_node).items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances[end]

def shortest_path_astar(graph, start, end, heuristic):
    # A* Search algorithm
    import heapq

    # Priority queue to fetch nodes with minimum cost
    priority_queue = [(0 + heuristic[start], 0, start, [start])]
    costs = {node: float('infinity') for node in graph.vertices()}
    costs[start] = 0

    while priority_queue:
        _, total_cost, current_node, path = heapq.heappop(priority_queue)

        if current_node == end:
            return path

        for neighbor, weight in graph.get_neighbors(current_node).items():
            new_cost = total_cost + weight
            if new_cost < costs[neighbor]:
                costs[neighbor] = new_cost
                priority_queue.append((new_cost + heuristic[neighbor], new_cost, neighbor, path + [neighbor]))

    return None

