    def __init__(self, position, parent=None):
        self.position = position
        self.parent = parent
        self.g = 0  # Cost from start to this node
        self.h = 0  # Heuristic cost from this node to the goal
        self.f = 0  # Total cost (g + h)

    def __lt__(self, other):
        return self.f < other.f

def heuristic(a, b):
    # Manhattan distance heuristic
    return abs(a.position[0] - b.position[0]) + abs(a.position[1] - b.position[1])

def reconstruct_path(came_from, current):
    total_path = [current.position]
    while current in came_from:
        current = came_from[current]
        total_path.append(current.position)
    total_path.reverse()
    return total_path

def astar_search(maze, start, goal):
    open_list = []
    heapq.heappush(open_list, (0, start))
    came_from = {}
    cost_so_far = {}

    came_from[start] = None
    cost_so_far[start] = 0

    while open_list:
        _, current = heapq.heappop(open_list)

        if current == goal:
            break

        for next_node in maze.get_neighbors(current):
            new_cost = cost_so_far[current] + maze.get_cost(current, next_node)
            if next_node not in cost_so_far or new_cost < cost_so_far[next_node]:
                cost_so_far[next_node] = new_cost
                priority = new_cost + heuristic(goal, next_node)
                heapq.heappush(open_list, (priority, next_node))
                came_from[next_node] = current

    return reconstruct_path(came_from, goal)

