Certainly! A widely used path search algorithm is the **Depth-First Search (DFS)**. DFS is a simple algorithm that explores as far as possible along each branch before backtracking. Here is a basic implementation of DFS in Python:

```python
class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return self.items == []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def top(self):
        return self.items[-1]

    def size(self):
        return len(self.items)

def dfs(graph, start, goal):
    if start not in graph:
        raise LookupError('Start node is not in the graph')

    stack = Stack()
    stack.push(start)
    visited = set()
    path = []

    while stack.size() > 0:
        node = stack.pop()
        if node == goal:
            path = [node]
            while node in graph:
                path.append(graph[node])
                node = graph[node]
            return path[::-1]
        if node not in visited:
            visited.add(node)
            stack.push(node)
            if node in graph:
                for neighbor in graph[node]:
                    stack.push(neighbor)

    return None

